<script lang="ts">import { totals, coupon, applyCoupon, notify } from '../stores/commerce'; import { money } from '../data/products'; let { checkout = false }: { checkout?: boolean } = $props(); let code = $state(''); let invalid = $state(false); function apply(e: SubmitEvent){e.preventDefault();invalid=!applyCoupon(code);if(!invalid){notify('Offer applied to your bag');code='';}}</script>
<aside class="order-summary"><h2>Your order summary</h2><div class="summary-line"><span>Subtotal</span><span>{money($totals.subtotal)}</span></div>{#if $totals.discount}<div class="summary-line discount"><span>Offer · {$coupon}</span><span>−{money($totals.discount)}</span></div>{/if}<div class="summary-line"><span>Demo delivery</span><span>{$totals.shipping?money($totals.shipping):'Complimentary'}</span></div><p class="muted small">Free delivery on a subtotal of ₹3,500 or more, before coupons. Otherwise ₹99.</p><div class="summary-total"><span>Total</span><strong>{money($totals.total)}</strong></div><form class="coupon-form" onsubmit={apply}><label for="coupon-code">Have a little something extra?</label><div><input id="coupon-code" placeholder="Offer code" bind:value={code} required/><button type="submit">Apply</button></div>{#if invalid}<span class="form-error" role="alert">Try WELCOME15 or HER10. One offer per bag.</span>{/if}</form>{#if $coupon}<p class="applied-code">{$coupon} applied <button onclick={()=>coupon.set('')}>Remove</button></p>{:else}<p class="muted small">Try WELCOME15 for 15% off your demo bag.</p>{/if}{#if !checkout}<a class="button dark full-width" href="#/checkout">Continue to demo checkout ↗</a>{/if}<div class="demo-notice">Demo only · no payment or shipment</div></aside>
